create table if not exists powerhouse_ops.cron_failure_triage(queue_id bigint primary key references powerhouse_ops.recovery_queue(id),jobid integer not null,runid bigint not null,failure text not null,resolution text not null default 'UNRESOLVED_DATABASE_CAPACITY',replay_allowed boolean not null default false check(replay_allowed=false),reviewed_at timestamptz not null default now());revoke all on powerhouse_ops.cron_failure_triage from public,anon,authenticated;create or replace function powerhouse_ops.triage_cron_failure_reviews(p_limit integer default 25) returns integer language plpgsql set search_path=pg_catalog,powerhouse_ops as $fn$ declare v_n integer;begin with selected as (select id,payload from powerhouse_ops.recovery_queue where task_key='cron_failure_review' and status='pending' and payload->>'replay_allowed'='false' and payload->>'failure'='job startup timeout' and (payload->>'jobid')::integer in(46,116,138,171) order by id limit least(greatest(p_limit,1),50) for update skip locked),inserted as (insert into powerhouse_ops.cron_failure_triage(queue_id,jobid,runid,failure) select id,(payload->>'jobid')::integer,(payload->>'runid')::bigint,payload->>'failure' from selected on conflict(queue_id) do nothing returning queue_id),marked as (update powerhouse_ops.recovery_queue q set status='succeeded',last_error='TRIAGED_ONLY_UNRESOLVED_NO_PROVIDER_REPLAY',locked_until=null from selected s where q.id=s.id returning q.id) select count(*) into v_n from marked;return v_n;end $fn$;revoke all on function powerhouse_ops.triage_cron_failure_reviews(integer) from public,anon,authenticated;
